// Unifica un mensaje y un toque de boton inline (callback_query) en la misma forma: { message, boton, callback_id }.
const u = $input.first().json; const cb = u.callback_query;
const BOTONES = {"sig:tienda":"Desglósalo por tienda","sig:mes":"Desglósalo por mes","sig:dev":"¿Cuánto se devolvió en ese mismo periodo?","sig:sec":"Muéstrame completa la sección del documento que citaste","sig:docs":"¿Qué otros documentos o secciones hablan de esto?","sig:tk":"¿Qué tickets hubo ese día en esa tienda?","menu:ventas":"menu:ventas","menu:inventario":"menu:inventario","menu:tickets":"menu:tickets","menu:politicas":"menu:politicas","q:v1":"¿Cuál fue la venta total de las cuatro tiendas en el trimestre?","q:v2":"¿Qué categoría vende más en T03?","q:v3":"¿Cuánto se devolvió en junio?","q:i1":"¿Qué productos de T02 están bajo su punto de reorden?","q:i2":"¿Qué caduca antes del 15 de septiembre en T04?","q:i3":"¿Qué productos perecederos debo retirar del anaquel hoy según la política?","q:t1":"¿Cuántos tickets críticos hubo?","q:t2":"¿Qué pasó con las ventas de T02 del 14 al 16 de julio?","q:t3":"¿Cumplimos el tiempo objetivo de solución de los tickets críticos?","q:p1":"¿Quién autoriza una devolución de 12,000 pesos?","q:p2":"¿Cuál es la tolerancia de merma en panadería?","q:p3":"¿Puedo darle el teléfono de un colaborador a un proveedor?"};
// Bot PUBLICO (los datos son sinteticos): sin allowlist. El limite de ritmo por chat esta en 'Limite por chat'.
if (cb) {
  return [{ json: { message: { ...cb.message, text: BOTONES[cb.data] ?? '', voice: undefined, audio: undefined, from: cb.from }, boton: cb.data, callback_id: cb.id } }];
}
return [{ json: { message: u.message, boton: null, callback_id: null } }];

