CREATE TABLE IF NOT EXISTS telegram_ritmo (chat_hash text, creado_en timestamptz DEFAULT now());
INSERT INTO telegram_ritmo (chat_hash) VALUES ($1);
DELETE FROM telegram_ritmo WHERE creado_en < now() - interval '1 hour';
SELECT count(*)::int AS en_ventana FROM telegram_ritmo WHERE chat_hash = $1 AND creado_en > now() - interval '5 minutes';

